begin;
do $$
declare uid uuid:=gen_random_uuid();ed uuid:=gen_random_uuid();cu uuid:=gen_random_uuid();sid uuid;esid uuid;csid uuid;guest uuid;aal1 uuid;target uuid:=gen_random_uuid();trace uuid:=gen_random_uuid();r jsonb;next_page jsonb;entry jsonb;failed boolean;day date;lo timestamptz;special uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email_confirmed_at) values(uid,now()),(ed,now()),(cu,now());insert into memocious_private.admin_users(user_id,role) values(uid,'owner'),(ed,'editor');
 sid:=public.memocious_session_open(repeat('1',64),repeat('2',64),uid,'admin','fixture','1');esid:=public.memocious_session_open(repeat('3',64),repeat('4',64),ed,'admin','fixture','1');csid:=public.memocious_session_open(repeat('5',64),repeat('6',64),cu,'customer','fixture','1');guest:=public.memocious_session_open(repeat('7',64),repeat('8',64),null,'guest',null,'1');aal1:=public.memocious_session_open(repeat('9',64),repeat('a',64),uid,'admin','fixture','1');
 perform public.memocious_session_mfa(sid,repeat('b',64),repeat('c',64),'fixture');perform public.memocious_session_mfa(esid,repeat('d',64),repeat('e',64),'fixture');
 insert into memocious.audit_log(created_at,actor_session_id,actor_kind,action,entity,entity_id,request_id,redacted_diff) select now()-make_interval(secs=>n),sid,'admin','fixture.edit','product',target,case when n=1 then trace else gen_random_uuid() end,'{"version":0,"count":0,"configured":false,"phone":"PRIVATE PHONE","tokens":{"refresh":"PRIVATE TOKEN"},"before":{"email":"PRIVATE CONTACT"},"scopeHash":"PRIVATE HASH"}' from generate_series(1,55)n;
 insert into memocious.audit_log(id,actor_session_id,actor_kind,action,entity,entity_id,request_id,redacted_diff) values(special,sid,'admin','PRIVATE EMAIL@example.invalid','PRIVATE ENTITY',sid,gen_random_uuid(),'{"version":"PRIVATE SECRET","count":9999999999999999,"configured":"PRIVATE CONFIG"}');
 execute 'set local role service_role';
 r:=public.memocious_owner_audit(sid,action_prefix=>'fixture.');
 if jsonb_array_length(r->'records')<>50 or r->>'hasMore'<>'true' or r->'nextCursor' is null then raise exception 'Audit page not bounded';end if;
 if r::text like '%PRIVATE%' or r->'records'->0 ?| array['actor_session_id','redacted_diff','encrypted_tokens'] then raise exception 'Audit payload leaked';end if;
 if r->'records'->0->'metadata' is distinct from '{"version":0,"count":0,"configured":false}'::jsonb or r->'records'->0->>'withheld'<>'true' then raise exception 'Safe zero/false metadata lost';end if;
 next_page:=public.memocious_owner_audit(sid,action_prefix=>'fixture.',cursor_at=>(r->'nextCursor'->>'at')::timestamptz,cursor_id=>(r->'nextCursor'->>'id')::uuid,as_of=>(r->>'asOf')::timestamptz);
 if jsonb_array_length(next_page->'records')<>5 or next_page->>'hasMore'<>'false' then raise exception 'Audit cursor page incorrect';end if;
 if exists(select 1 from jsonb_array_elements(r->'records')a join jsonb_array_elements(next_page->'records')b on a->>'id'=b->>'id') then raise exception 'Audit cursor overlap';end if;
 if jsonb_array_length(public.memocious_owner_audit(sid,action_prefix=>'fixture.',entity_key=>target,request_key=>trace)->'records')<>1 then raise exception 'Exact UUID filter';end if;
 select memocious_private.audit_entry(a) into entry from memocious.audit_log a where id=special;if entry::text like '%PRIVATE%' or entry->>'action'<>'other' or entry->'metadata'<>'{}'::jsonb then raise exception 'Unsafe metadata not masked';end if;
 select memocious_private.audit_entry(a) into entry from memocious.audit_log a where actor_session_id=sid and entity='session' limit 1;if entry->>'entityId' is not null then raise exception 'Session identifier leaked';end if;
 failed:=false;begin perform public.memocious_owner_audit(esid);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Editor audit read';end if;
 failed:=false;begin perform public.memocious_owner_audit(aal1);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Unverified owner audit read';end if;
 failed:=false;begin perform public.memocious_owner_audit(csid);exception when invalid_authorization_specification then failed:=true;end;if not failed then raise exception 'Customer audit read';end if;
 failed:=false;begin perform public.memocious_owner_audit(guest);exception when invalid_authorization_specification then failed:=true;end;if not failed then raise exception 'Guest audit read';end if;
 failed:=false;begin perform public.memocious_owner_audit(sid,from_day=>'2026-01-01',to_day=>'2026-04-01');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Unbounded audit range';end if;
 failed:=false;begin perform public.memocious_owner_audit(sid,cursor_at=>now());exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Unpaired cursor';end if;
 failed:=false;begin perform public.memocious_owner_audit(sid,as_of=>now()+interval '1 second');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Future snapshot';end if;
 execute 'reset role';
 insert into memocious.audit_log(created_at,actor_kind,action,entity,request_id) values((r->>'asOf')::timestamptz+interval '1 microsecond','job','fixture.later','product',gen_random_uuid());
 execute 'set local role service_role';
 if public.memocious_owner_audit(sid,action_prefix=>'fixture.',as_of=>(r->>'asOf')::timestamptz)->'records' is distinct from r->'records' then raise exception 'Snapshot included later write';end if;
 execute 'reset role';day:=(now()at time zone 'Asia/Kolkata')::date-2;lo:=day::timestamp at time zone 'Asia/Kolkata';
 insert into memocious.audit_log(created_at,actor_kind,action,entity,request_id) values(lo-interval '1 microsecond','job','boundary.test','product',gen_random_uuid()),(lo,'job','boundary.test','product',gen_random_uuid()),(lo+interval '1 day'-interval '1 microsecond','job','boundary.test','product',gen_random_uuid()),(lo+interval '1 day','job','boundary.test','product',gen_random_uuid());
 execute 'set local role service_role';if jsonb_array_length(public.memocious_owner_audit(sid,from_day=>day,to_day=>day,action_prefix=>'boundary.')->'records')<>2 then raise exception 'Kolkata date boundary';end if;
 execute 'reset role';update memocious_private.app_sessions set mfa_verified_at=now()-interval '6 minutes' where id=sid;execute 'set local role service_role';
 failed:=false;begin perform public.memocious_owner_audit(sid);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Stale MFA audit read';end if;
 execute 'reset role';update memocious_private.app_sessions set mfa_verified_at=now() where id=sid;update memocious_private.admin_users set active=false where user_id=uid;execute 'set local role service_role';
 failed:=false;begin perform public.memocious_owner_audit(sid);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Revoked owner role audit read';end if;
 execute 'reset role';
end $$;
rollback;
select 'PASS: owner-only recent-MFA audit, editor/customer/guest/aal1/revoked denial, safe zero/false metadata, unknown fields/session IDs withheld, cursor bounds/snapshot/no overlap, UUID filters and Kolkata date boundaries' result;
